(* [comment removed for export] *)
Context {PINS : LeptPins}.
Lemma live_apart : forall C A m md (p q : word) (n k : Z), Cok C -> W C A m md ->
  live A p = Some n -> live A q = Some k -> p <> q -> 0 <= n -> 0 <= k ->
