Lemma selname_at_frame_blk : forall C A m md m' T name nm (p n : Z), Cok C -> W C A m md -> T < 2 ^ 64 ->
  selname_at T A m name nm -> live A (Z_to_bv 64 p) = Some n -> 0 <= p < 2 ^ 64 -> 0 <= n -> name <> p ->
  (forall x : word, ~ (p <= u x < p + n) -> m' x = m x) ->
